import { randomUUID } from 'node:crypto';
import type { Server } from 'node:http';
import type { AddressInfo } from 'node:net';

import type { Application } from '../src/composition.js';
import { createLocalApiHandler } from '../src/http/local-api.js';
import { createHttpServer } from '../src/http/server.js';
import { SessionCookies } from '../src/http/session-cookie.js';

export interface ApiResponse<T = unknown> {
  readonly status: number;
  readonly body: T;
  readonly headers: Headers;
}

export interface RequestOptions {
  readonly body?: unknown;
  /** Idempotency key; generated by default for mutations, `false` to omit. */
  readonly key?: string | false;
  readonly headers?: Record<string, string>;
  /** Sends bytes instead of JSON. */
  readonly raw?: Uint8Array;
}

export async function startServer(
  app: Application,
): Promise<{ baseUrl: string; close: () => Promise<void> }> {
  const server: Server = createHttpServer(
    createLocalApiHandler(app, new SessionCookies('test-secret')),
  );
  await new Promise<void>((resolve) => server.listen(0, '127.0.0.1', resolve));
  const { port } = server.address() as AddressInfo;
  return {
    baseUrl: `http://127.0.0.1:${port}/api/v1`,
    close: () =>
      new Promise((resolve) => {
        server.closeAllConnections();
        server.close(() => resolve());
      }),
  };
}

/** A browser-like client with its own session cookie. */
export class ApiClient {
  public cookie: string | undefined;

  public constructor(private readonly baseUrl: string) {}

  public static async signedIn(baseUrl: string, userId: string) {
    const client = new ApiClient(baseUrl);
    const response = await client.request('PUT', '/session', {
      body: { userId },
    });
    if (response.status !== 200) {
      throw new Error(`Sign-in failed with ${response.status}`);
    }
    return client;
  }

  public get<T = any>(path: string): Promise<ApiResponse<T>> {
    return this.request<T>('GET', path);
  }

  public async request<T = any>(
    method: string,
    path: string,
    options: RequestOptions = {},
  ): Promise<ApiResponse<T>> {
    const headers: Record<string, string> = { ...options.headers };
    if (this.cookie !== undefined) {
      headers.Cookie = this.cookie;
    }
    if (method !== 'GET' && options.key !== false) {
      headers['Idempotency-Key'] = options.key ?? `test-${randomUUID()}`;
    }
    let body: BodyInit | undefined;
    if (options.raw !== undefined) {
      body = new Uint8Array(options.raw);
    } else if (options.body !== undefined) {
      headers['Content-Type'] ??= 'application/json';
      body =
        typeof options.body === 'string'
          ? options.body
          : JSON.stringify(options.body);
    }

    const response = await fetch(`${this.baseUrl}${path}`, {
      method,
      headers,
      ...(body === undefined ? {} : { body }),
    });
    const setCookie = response.headers.get('set-cookie');
    if (setCookie !== null) {
      const value = setCookie.split(';')[0]!;
      this.cookie = value.endsWith('=') ? undefined : value;
    }
    const type = response.headers.get('content-type') ?? '';
    const parsed: unknown = type.includes('application/json')
      ? await response.json()
      : new Uint8Array(await response.arrayBuffer());
    return {
      status: response.status,
      body: parsed as T,
      headers: response.headers,
    };
  }
}
